import json,re,html
s=json.load(open('source.json')); a=json.load(open('answer.json'))
def clean(x): return ' '.join(html.unescape(re.sub(r'<["'^>]*>'"',' ',x)).split())
for old,new in zip(s[:7],a[:7]):
 print('\\nARTICLE',old['number'])
 if old['number'] in {'2 sexies','2 undecies'}:
  print('SOURCE',clean(old['source_xml']))
  print('PROPOSITION',new['proposed_xml'])
 else:
  sp=re.findall(r'<p>(.*?)</p>',old['source_xml'],re.S)
  np=re.findall(r'<p>(.*?)</p>',new['proposed_xml'],re.S)
  for i,(x,y) in enumerate(zip(sp,np),1):
   print(str(i)+' S:',clean(x))
   print(str(i)+' P:',clean(y))
  for i,table in enumerate(re.findall(r'<table>.*?</table>',new['proposed_xml'],re.S),1):
   print('TABLEAU',i)
   for row in re.findall(r'<tr>(.*?)</tr>',table,re.S): print(' | '.join(clean(c) for c in re.findall(r'<t[hd]["'^>]*>(.*?)</t[hd]>'"',row,re.S)))
 print('NOTES SOURCE',clean(old['source_notes_xml']))
PY"

